'use strict';

const http = require('http');
const https = require('https');
const url = require('url');

function normalizeHeaders(headers) {
  const result = {};
  for (const key of Object.keys(headers || {})) {
    result[key.toLowerCase()] = headers[key];
  }
  return result;
}

function bodyToString(data) {
  if (data === undefined || data === null) return '';
  if (typeof data === 'string' || Buffer.isBuffer(data)) return data;
  if (typeof data === 'number' || typeof data === 'boolean') return String(data);
  return JSON.stringify(data);
}

function requestOnce(config, requestBody, redirectCount = 0) {
  return new Promise((resolve, reject) => {
    const parsed = new url.URL(config.url);
    const isHttps = parsed.protocol === 'https:';
    const client = isHttps ? https : http;
    const headers = normalizeHeaders(config.headers || {});

    if (requestBody !== '' && !headers['content-type']) {
      headers['content-type'] = 'application/json';
    }
    if (requestBody !== '' && !headers['content-length']) {
      headers['content-length'] = Buffer.byteLength(requestBody);
    }

    const options = {
      protocol: parsed.protocol,
      hostname: parsed.hostname,
      port: parsed.port || (isHttps ? 443 : 80),
      path: `${parsed.pathname}${parsed.search}`,
      method: config.method || 'GET',
      headers
    };

    const req = client.request(options, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume();
        if (redirectCount >= 5) {
          reject(new Error('Too many redirects'));
          return;
        }
        const nextUrl = new url.URL(res.headers.location, config.url).toString();
        const nextConfig = { ...config, url: nextUrl };
        requestOnce(nextConfig, requestBody, redirectCount + 1).then(resolve, reject);
        return;
      }

      if (config.responseType === 'stream') {
        const response = {
          data: res,
          status: res.statusCode,
          statusText: res.statusMessage || '',
          headers: res.headers,
          config
        };
        const validateStatus = config.validateStatus || (status => status >= 200 && status < 300);
        if (validateStatus(response.status)) {
          resolve(response);
        } else {
          const error = new Error(`Request failed with status code ${response.status}`);
          error.response = response;
          error.config = config;
          reject(error);
        }
        return;
      }

      const chunks = [];
      res.on('data', chunk => chunks.push(chunk));
      res.on('end', () => {
        const raw = Buffer.concat(chunks);
        const contentType = res.headers['content-type'] || '';
        let data = raw;
        if (config.responseType === 'arraybuffer') {
          data = raw;
        } else {
          data = raw.toString('utf8');
          if (contentType.includes('application/json')) {
            try {
              data = JSON.parse(data);
            } catch (_) {
              // Keep the original text when the response is not valid JSON.
            }
          }
        }

        const response = {
          data,
          status: res.statusCode,
          statusText: res.statusMessage || '',
          headers: res.headers,
          config
        };

        const validateStatus = config.validateStatus || (status => status >= 200 && status < 300);
        if (validateStatus(response.status)) {
          resolve(response);
        } else {
          const error = new Error(`Request failed with status code ${response.status}`);
          error.response = response;
          error.config = config;
          reject(error);
        }
      });
    });

    req.on('error', reject);
    if (config.timeout) {
      req.setTimeout(config.timeout, () => {
        req.destroy(new Error(`timeout of ${config.timeout}ms exceeded`));
      });
    }
    req.end(requestBody);
  });
}

async function axios(configOrUrl, configOrData, maybeConfig) {
  let config;
  if (typeof configOrUrl === 'string') {
    config = maybeConfig || {};
    config.url = configOrUrl;
    config.data = configOrData;
  } else {
    config = { ...configOrUrl };
  }
  config.method = (config.method || 'GET').toUpperCase();
  if (typeof config.url === 'string') {
    config.url = config.url.trim();
  }
  if (!config.url) {
    throw new Error('axios requires a URL');
  }
  const requestBody = config.method === 'GET' || config.method === 'HEAD' ? '' : bodyToString(config.data);
  return requestOnce(config, requestBody);
}

axios.get = (url, config = {}) => axios({ ...config, url, method: 'GET' });
axios.post = (url, data, config = {}) => axios({ ...config, url, method: 'POST', data });
axios.put = (url, data, config = {}) => axios({ ...config, url, method: 'PUT', data });
axios.patch = (url, data, config = {}) => axios({ ...config, url, method: 'PATCH', data });
axios.delete = (url, config = {}) => axios({ ...config, url, method: 'DELETE' });
axios.head = (url, config = {}) => axios({ ...config, url, method: 'HEAD' });
axios.all = Promise.all;
axios.spread = callback => array => callback(...array);

module.exports = axios;
